costs = {cell('W1::Providers', f'D{r}'): num('W1::Providers', f'C{r}') for r in range(42, 48)}
coverage = {}
for r in range(804, 814):
    p = cell('W1::Coverage', f'C{r}')
    a = cell('W1::Coverage', f'D{r}')
    coverage.setdefault(p, set()).add(a)
required = {cell('W1::Required', f'C{r}') for r in range(42, 46)}
providers = list(costs.keys())
best_cost = float('inf')
for i in range(1 << len(providers)):
    subset = [providers[j] for j in range(len(providers)) if (i & (1 << j))]
    covered = set()
    for p in subset:
        covered.update(coverage.get(p, set()))
    if required.issubset(covered):
        cost = sum(costs[p] for p in subset)
        if cost < best_cost:
            best_cost = cost
result = int(best_cost)

